def _best_plant_crop(observation: Dict[str, Any]) -> str:
    seeds = observation.get("private", {}).get("seeds", {}) or {}
    for crop in CROPS:
        if seeds.get(crop, 0) > 0:
            return crop
    return "WHEAT"


